// @FIGURE_CODE_BEGIN
var W = 600, H = 470;
var draw = SVG().addTo('#container').size('100%', '100%');
draw.viewbox(0, 0, W, H);

// Unit direction: shallow up-and-to-the-right (~12°), screen coords
var ang = -12 * Math.PI / 180;
var ux = Math.cos(ang), uy = Math.sin(ang);
var VLEN = 85; // pixel length of v

// Arrowhead markers created on THIS draw instance and attached directly
function mkMarker(color) {
  return draw.marker(10, 8, function (add) {
    add.path('M0,0 L10,4 L0,8 Z').fill(color);
  }).attr({ refX: 9, refY: 4, orient: 'auto-start-reverse', markerUnits: 'userSpaceOnUse' });
}

var mainG = draw.group();
var overlay = false;
var kVal = 1;
var kvRevealed = false; // purple arrow hidden until slider touched or a later step

var ORG = { x: 120, y: 250 }; // shared origin in overlay mode

var specs = [
  { key: 'navy',   s: 3,    color: '#1b3b6f', label: '3v' },
  { key: 'orange', s: 1,    color: '#e8590c', label: 'v' },
  { key: 'teal',   s: 0.5,  color: '#0e8a8a', label: 'half' }, // stacked ½ fraction
  { key: 'red',    s: -1,   color: '#d62728', label: '−v' },
  { key: 'purple', s: null, color: '#7b2fbf', label: 'kv' }    // dynamic
];

var rows = [70, 175, 280, 385, 385];
var items = [];

function makeLabel(g, sp) {
  if (sp.label === 'half') {
    // True stacked fraction: 1 over 2, then bold italic v
    var t = g.text(function (add) {
      add.tspan('1').attr({ 'font-size': 13, dy: -10 });
      add.tspan('v').attr({ 'font-size': 20, 'font-style': 'italic', 'font-weight': 'bold', dx: 6, dy: 8 });
    }).font({ family: 'Georgia, serif', size: 13 }).fill('#222');
    var frac = g.line(0, 0, 14, 0).stroke({ color: '#222', width: 1.2 });
    return { text: t, frac: frac, isFrac: true };
  }
  var t2 = g.text(sp.label).font({ family: 'Georgia, serif', size: 20, style: 'italic', weight: 'bold' })
    .fill(sp.key === 'purple' ? '#7b2fbf' : '#222');
  t2.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 4, 'stroke-linejoin': 'round' });
  return { text: t2, frac: null, isFrac: false };
}

specs.forEach(function (sp, i) {
  var g = mainG.group();
  var marker = mkMarker(sp.color);
  var line = g.line(0, 0, 1, 1)
    .stroke({ color: sp.color, width: 3, linecap: 'round' })
    .marker('end', marker);
  var dot = g.circle(9).fill('#111');
  var lab = makeLabel(g, sp);
  g.css('cursor', 'pointer');
  items.push({ g: g, line: line, dot: dot, lab: lab, sp: sp, row: i });
});

// Overlay extras: emphasized origin + dashed ray line
var rayLine = mainG.line(0, 0, 1, 1).stroke({ color: '#999', width: 1.5, dasharray: '6,5' }).opacity(0);
var orgDot = mainG.circle(13).fill('#111').opacity(0);
var orgLab = mainG.text('common tail').font({ family: 'sans-serif', size: 12 }).fill('#555').opacity(0);

function fmtK(k) {
  if (k === 0) return '0';
  return (Math.round(k * 100) / 100).toString().replace('-', '−') + 'v';
}

function place(item) {
  var sp = item.sp;
  var s = (sp.s === null) ? kVal : sp.s;
  var tail, baseX;
  if (overlay) {
    tail = { x: ORG.x, y: ORG.y };
  } else {
    baseX = (sp.s === -1) ? 240 : 50;           // red dot sits at right end
    if (sp.s === null) baseX = (s < 0) ? 240 : 50;
    tail = { x: baseX, y: rows[item.row] };
  }
  var len = Math.abs(s) * VLEN;
  var dir = (s < 0) ? -1 : 1;
  var head = (s === 0)
    ? { x: tail.x, y: tail.y }
    : { x: tail.x + dir * ux * len, y: tail.y + dir * uy * len };

  item.line.plot(tail.x, tail.y, head.x, head.y);
  item.line.opacity(s === 0 ? 0 : 1);
  item.dot.center(tail.x, tail.y);

  var lx = head.x + 12, ly = head.y - 18;
  if (s === 0) { lx = tail.x + 12; ly = tail.y - 12; }
  if (sp.s === null) item.lab.text.text(fmtK(kVal));

  if (item.lab.isFrac) {
    item.lab.text.move(lx, ly);
    // fraction bar under the "1", before the v
    item.lab.frac.plot(lx + 1, ly + 6, lx + 15, ly + 6);
    // second stacked digit "2" handled by separate tspan? add via line only; draw 2 below
  } else {
    item.lab.text.move(lx, ly);
  }
}

// Add the stacked "2" for the half label once
(function () {
  var teal = items[2];
  teal.lab.denom = teal.g.text('2').font({ family: 'Georgia, serif', size: 13 }).fill('#222');
})();

function placeAll() {
  items.forEach(function (it) {
    place(it);
    if (it.lab.isFrac) {
      var t = it.lab.text;
      it.lab.denom.move(t.x() + 1, t.y() + 14);
    }
  });
  // purple visibility
  var purple = items[4];
  purple.g.opacity(kvRevealed ? 1 : 0);

  var ex = 3.6 * VLEN;
  if (overlay) {
    rayLine.plot(ORG.x - ux * ex, ORG.y - uy * ex, ORG.x + ux * ex, ORG.y + uy * ex);
    rayLine.opacity(0.7);
    orgDot.center(ORG.x, ORG.y).opacity(1);
    orgLab.move(ORG.x + 16, ORG.y + 12).opacity(1);
  } else {
    rayLine.opacity(0); orgDot.opacity(0); orgLab.opacity(0);
  }
}

// Interactions
function update_scalarSlider(v) {
  kVal = v;
  kvRevealed = true;
  placeAll();
}
function toggle_layoutView(on) {
  overlay = !!on;
  placeAll();
}

// Hover / click
var tips = {
  navy: '3v = 3·v: three times the length, identical direction.',
  orange: 'v: the reference vector.',
  teal: '½v: half the length, same direction.',
  red: '−v: same length as v, flipped 180°.',
  purple: 'kv: drag the slider to stretch, shrink, or flip this arrow.'
};
items.forEach(function (it) {
  it.g.on('mousemove', function (e) { showTooltip(tips[it.sp.key], e); })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () {
      showPopup('Scalar multiplication',
        'Multiplying a vector by a positive scalar k changes only its length — never its heading. ' +
        'A negative scalar flips the vector 180°, and k = 0 collapses it to a point. This arrow: ' +
        (it.sp.s === null ? fmtK(kVal) : it.sp.label === 'half' ? '½v' : it.sp.label) + '.');
    });
});

// Demo steps
var steps = [
  { narration: 'All four arrows lie on the same shallow slope. 3v, v, and ½v all point up-and-to-the-right — only their lengths differ, in exact proportion to the scalar.',
    state: { layout: false, k: 1, reveal: false } },
  { narration: 'Drag k upward and the purple arrow stretches toward 3v; drag it toward 0 and it shrinks to the origin dot. The heading never changes while k stays positive.',
    state: { layout: false, k: 3, reveal: true } },
  { narration: 'Push k below 0: the arrow flips to point down-and-to-the-left, exactly like the red −v arrow. A negative scalar reverses direction; |k| still sets the length.',
    state: { layout: false, k: -1, reveal: true } },
  { narration: 'Switch to the shared-tail view: every arrow now starts at the same dot, so their tips line up along a single ray for positive k and along the opposite ray for negative k.',
    state: { layout: true, k: 1.5, reveal: true } }
];
var stepIdx = 0;
function applyStep(i) {
  stepIdx = Math.max(0, Math.min(steps.length - 1, i));
  var st = steps[stepIdx];
  document.getElementById('demoNarration').textContent = st.narration;
  document.getElementById('stepLabel').textContent = (stepIdx + 1) + ' / ' + steps.length;
  document.getElementById('scalarSliderInput').value = st.state.k;
  document.getElementById('scalarSliderVal').value = st.state.k;
  kVal = st.state.k;
  kvRevealed = st.state.reveal;
  document.getElementById('layoutViewInput').checked = st.state.layout;
  overlay = st.state.layout;
  placeAll();
}
function nextStep() { applyStep(stepIdx + 1); }
function prevStep() { applyStep(stepIdx - 1); }

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

