};
items.forEach(function (it) {
  it.g.on('mousemove', function (e) { showTooltip(tips[it.sp.key], e); })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () {
      showPopup('Scalar multiplication',
        'Multiplying a vector by a positive scalar k changes only its length — never its heading. ' +
        'A negative scalar flips the vector 180°, and k = 0 collapses it to a point. This arrow: ' +
        (it.sp.s === null ? fmtK(kVal) : it.sp.label === 'half' ? '½v' : it.sp.label) + '.');
    });
});

// Demo steps
